sys_flow_trigger_auto_script.script:
var triggerId = gs.getProperty('x_enno_gatenow.trigger_timer_208f17', '');
if (triggerId) {
    sn_flow_trigger.FlowTriggerAPI.fireTimerTrigger(triggerId);
} else {
    gs.warn('GateNow: System property x_enno_gatenow.trigger_timer_208f17 is not configured.');
}

